package com.vandorlabs.neoforge.navigation.observer;
import java.util.*;import com.vandorlabs.machines.CoreLayout;import com.vandorlabs.navigation.NavigationRange;import com.vandorlabs.redstone.ChannelList;import com.vandorlabs.neoforge.gear.*;import net.minecraft.core.*;import net.minecraft.core.component.DataComponents;import net.minecraft.nbt.CompoundTag;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.item.component.CustomData;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.phys.*;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.server.ServerStartedEvent;import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Ordinary arm placement with a real inverted observer, fractional source projection and cold reversal. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeObserverArmRuntimeChecks {
 private static final BlockPos OBS=new BlockPos(31,64,31),ARM=OBS.above(2);private static ServerLevel world;private static Actor actor;private static int stage,ticks,checks,samples;private static int firstRadius=-1;private static boolean changed,done;private static UUID identity;private static boolean protect;private static BlockPos protectedPart;
 private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer{Actor(ServerLevel w){super(w,new com.mojang.authlib.GameProfile(new UUID(0,211032),"ObserverArmRuntime"));}}
 private static String phase(){return System.getProperty("vandorlabs.observerRuntimePhase","");}private static boolean enabled(){return Boolean.getBoolean("vandorlabs.observerRuntimeChecks")&&phase().startsWith("arm-");}private static void need(boolean valid,String why){checks++;if(!valid)throw new AssertionError("Observer arm stage="+stage+" ticks="+ticks+": "+why);}private static NativeGearEntity arm(){return (NativeGearEntity)world.getBlockEntity(ARM);}
 @SubscribeEvent public static void started(ServerStartedEvent e){if(!enabled())return;try{world=e.getServer().overworld();for(int x=0;x<=3;x++)for(int z=0;z<=3;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);actor.setPos(27.5,65,27.5);if(phase().endsWith("-read")){stage=5;return;}for(var p:BlockPos.betweenClosed(OBS.offset(-7,-7,-7),OBS.offset(7,7,7)))world.setBlock(p,Blocks.AIR.defaultBlockState(),3);world.setBlock(OBS,NativeObserverBindings.CORES.get("standalone_antenna").defaultBlockState(),3);var t=(NativeObserverEntity)world.getBlockEntity(OBS);identity=t.key();t.configure(ChannelList.of(71),256);var d=NativeObserverDesigns.scaled("standalone_antenna",4);var layout=new CoreLayout(d.width(),d.height(),d.depth(),Direction.NORTH.get3DDataValue(),0,0);for(int x=0;x<d.width();x++)for(int y=0;y<d.height();y++)for(int z=0;z<d.depth();z++){var p=OBS.offset(layout.x(x,z),-y,layout.z(x,z));if(!p.equals(OBS))world.setBlock(p,layout.frame(x,y,z)?NativeObserverFormation.matter().defaultBlockState():Blocks.AIR.defaultBlockState(),3);}need(NativeObserverTransactions.request(t,actor,true),"observer formation queued");stage=0;}catch(Throwable bad){fail(bad);}}
 private static void placeArms(){world.setBlock(ARM.above(),Blocks.STONE.defaultBlockState(),3);var settings=NativeGearSettings.defaults().choices();settings.putBoolean("RotatePayload",phase().contains("rotate"));settings.putBoolean("CarryLoad",true);settings.putInt("LoadHeight",8);settings.putDouble("ActiveExtension",2);var data=new CompoundTag();data.put(NativeGearItem.SETTINGS,settings);var held=new ItemStack(NativeGearBindings.ITEMS.get((phase().contains("rotate")||phase().contains("level")?NativeGearDefinition.ROTATING:NativeGearDefinition.EXTENDER).id),2);held.set(DataComponents.CUSTOM_DATA,CustomData.of(data));actor.setItemInHand(InteractionHand.MAIN_HAND,held);for(int part=0;part<2;part++){var support=ARM.above(1-part);var hit=new BlockHitResult(Vec3.atCenterOf(support).add(0,-.5,0),Direction.DOWN,support,false);need(actor.gameMode.useItemOn(actor,world,held,InteractionHand.MAIN_HAND,hit).consumesAction(),"real downward arm section placement "+part);}need(held.isEmpty(),"two Survival arm items consumed");actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);}
 @SubscribeEvent public static void tick(ServerTickEvent.Post e){if(!enabled()||world==null||done)return;try{need(++ticks<1800,"bounded arm completion");if(stage==0){var t=(NativeObserverEntity)world.getBlockEntity(OBS);if(!t.formed()||!t.available())return;need(t.inverted()&&t.design().width()==4&&t.design().height()==8,"double-size4x8x4 core-at-top observer formed");sourceFootprint(t);placeArms();stage=1;return;}var arm=arm();if(arm==null||arm.inert()||!arm.controller()||!arm.completeMembers())return;if(stage==1){need(arm.assembly().columnHeight()==2,"two native downward sections formed");arm.getPersistentData().putUUID("ObserverSmokeIdentity",identity);arm.setChanged();if(phase().equals("arm-save")){protect=true;protectedPart=((NativeObserverEntity)world.getBlockEntity(OBS)).cell(3,7,3);}arm.authorize(actor);need(arm.command(false),"ordinary observer-bearing arm activates");stage=protect?10:2;return;}
 if(stage==10){if(!arm.blocked())return;need(arm.error().contains("protection"),"external far-member protection refuses capture");need(world.getBlockEntity(OBS) instanceof NativeObserverEntity source&&source.key().equals(identity)&&source.available(),"refused capture retains original usable native owner");sourceFootprint((NativeObserverEntity)world.getBlockEntity(OBS));protect=false;arm.authorize(actor);need(arm.command(false),"same movement retries after external protection removed");stage=2;return;}
 if(stage==2||stage==6){need(!arm.blocked(),"observer motion unobstructed "+arm.error());if(arm.progress()>0&&arm.progress()<1&&arm.payload()!=null&&!arm.payload().materialized()){var areas=NativeNavigationSources.matching(world,OBS.north(4),ChannelList.of(71));need(areas.size()==1,"one captured source during fractional movement");NativeObserverPayloadSources.visit(world,new AABB(OBS).inflate(64),(position,physicalRadius,channels,range,radar,sentinel)->{need(areas.getFirst().radius()==physicalRadius&&physicalRadius==NavigationRange.radius(NavigationRange.SENTINEL_BASE,position.y,2),"coverage follows physical source height");if(firstRadius<0)firstRadius=areas.getFirst().radius();else changed|=firstRadius!=areas.getFirst().radius();samples++;});}double target=stage==2?0:1;if(arm.progress()!=target||busy(arm))return;need(NativeNavigationSources.matching(world,OBS.north(4),ChannelList.of(71)).size()==1,"one source at stopped native endpoint");verifyOwnership(arm);if(stage==2){need(samples>1&&changed,"multiple physical-height samples change radius");world.getServer().saveEverything(false,true,true);finish(phase());}else finish(phase());return;}
 if(stage==5){need(arm.getPersistentData().hasUUID("ObserverSmokeIdentity"),"cold fixture retained source identity witness");identity=arm.getPersistentData().getUUID("ObserverSmokeIdentity");verifyOwnership(arm);need(arm.progress()==0,"cold arm retained active endpoint");need(NativeNavigationSources.matching(world,OBS.north(4),ChannelList.of(71)).size()==1,"cold source survives endpoint restoration");arm.authorize(actor);need(arm.command(true),"cold arm reverses with same observer");stage=6;}
 }catch(Throwable bad){fail(bad);}}
 @SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.LOWEST) public static void externalProtection(net.neoforged.neoforge.event.level.BlockEvent.BreakEvent event){if(!enabled()||!protect||event.getLevel()!=world||!event.getPos().equals(protectedPart))return;need(NativeObserverCapture.isProbe(event),"only exact movement event is exempt from observer mining behavior");var nested=new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(world,event.getPos(),event.getState(),actor);need(!NativeObserverCapture.isProbe(nested),"different/reentrant real break event receives no exemption");need(!world.setBlock(event.getPos(),Blocks.AIR.defaultBlockState(),3),"protection probe grants no world mutation privilege");event.setCanceled(true);}
 private static void sourceFootprint(NativeObserverEntity t){need(t.design().width()==4&&t.design().height()==8&&t.saveWithoutMetadata(world.registryAccess()).getInt("ObserverWidth")==4,"double-size actual dimensions and width NBT");for(int x=0;x<4;x++)for(int y=0;y<8;y++)for(int z=0;z<4;z++){var p=t.cell(x,y,z);if(p.equals(t.getBlockPos()))continue;need(world.getBlockEntity(p) instanceof NativeObserverPartEntity part&&part.root()==t,"double-size source has127 exact owned members");}}
 private static void verifyOwnership(NativeGearEntity arm){int nativeOwners=0;NativeObserverEntity found=null;for(int x=0;x<=3;x++)for(int z=0;z<=3;z++){var chunk=world.getChunkSource().getChunkNow(x,z);if(chunk==null)continue;for(var tile:chunk.getBlockEntities().values())if(tile instanceof NativeObserverEntity source&&!source.inert()&&source.formed()&&source.key().equals(identity)){nativeOwners++;found=source;}}boolean captured=arm.payload()!=null&&!arm.payload().materialized();if(captured){need(nativeOwners==0,"captured source has no second native owner");int cores=0,parts=0;for(var cell:arm.payloadView().cells()){if(cell.state().getBlock() instanceof NativeObserverCoreBlock){cores++;var tag=cell.projection();need(tag.getInt("ObserverWidth")==4&&tag.hasUUID("ObserverKey")&&tag.getUUID("ObserverKey").equals(identity),"captured scaled source keeps dimensions and exact identity");}else if(cell.state().getBlock() instanceof NativeObserverPartBlock)parts++;}need(cores==1&&parts==127,"captured source retains complete4x8x4 footprint");}else{need(nativeOwners==1,"native endpoint has exactly one source owner");sourceFootprint(found);}}
 private static boolean busy(NativeGearEntity arm){try{var method=NativeGearJournal.class.getDeclaredMethod("busy",NativeGearEntity.class);method.setAccessible(true);return (Boolean)method.invoke(null,arm);}catch(ReflectiveOperationException bad){throw new AssertionError(bad);}}
 private static void finish(String phase){done=true;System.out.println("[vandorlabs][observer-runtime] "+phase+" PASS checks="+checks+" samples="+samples+" ordinaryPlacement/fractionalHeight/coldReversal");world.getServer().halt(false);}private static void fail(Throwable bad){bad.printStackTrace();System.err.println("[vandorlabs][observer-runtime] FAIL "+bad);done=true;if(world!=null)world.getServer().halt(false);}
 private NativeObserverArmRuntimeChecks(){}
}
